import {defaults,limits,validate,simulate,panel,current,equilibrium,domainWarnings} from './engine.js';
const $=id=>document.getElementById(id);const palette={po:'#0078ae',dqn:'#b44d21',mpp:'#526779'};let policy,result,view='p',cursor=0,timer;
const fields={panel:[['g0','Initial irradiance','W/m²',1,'wide'],['g1','After step','W/m²',1,'wide'],['temp','Cell temperature','°C',1],['voc','Reference Voc','V',.1],['isc','Reference Isc','A',.01],['shape','Curve shape a','',1]],control:[['duration','Duration','s',1],['dt','Sample period','s',.01],['step','Voltage step','V',.01],['tau','Response time τ','s',.01],['noise','Sensor noise','± %',.1],['epsilon','DQN exploration ε','',.01],['seed','Random seed','',1,'wide']],converter:[['ratio','Effective ratio m','',.000001,'wide'],['bus','Fixed bus','V',.1],['cap','Transfer Ceff','µF',1],['k','Transfer factor k','',.1],['rfast','Rfast','Ω',.01],['fmin','Minimum f','kHz',.1],['fmax','Maximum f','kHz',1],['finit','Initial f','kHz',.1,'wide']]};
for(const [group,list] of Object.entries(fields))$(group+'-fields').innerHTML=list.map(([key,name,unit,step,wide])=>`<div class="field ${wide||''}"><label for="${key}">${name}<span class="unit">${unit}</span></label><input id="${key}" type="number" value="${defaults[key]}" min="${limits[key][0]}" max="${limits[key][1]}" step="${step}" inputmode="decimal"></div>`).join('');
const fmt=(x,d=2)=>x===null||!Number.isFinite(x)?'N/A':x.toFixed(d);const round=(x,d=4)=>x===null?null:Number(x.toFixed(d));
function read(){return Object.fromEntries([...Object.keys(limits).map(k=>[k,$(k).value.trim()===''?NaN:Number($(k).value)]),['profile',$('profile').value]]);}
function inputState(){const step=$('profile').value==='step';$('g1').disabled=!step;$('g1').parentElement.hidden=!step;}
function run(p=read()){try{validate(p);if(!policy)return;result=simulate(p,policy);cursor=result.po.length-1;$('cursor').max=cursor;$('cursor').value=cursor;$('error').hidden=true;$('export').disabled=false;$('status').textContent=`${p.duration} s · ${p.dt} s sampling · seed ${p.seed}`;renderMetrics();renderWarnings();render();return result;}catch(e){$('error').textContent=e.message;$('error').hidden=false;$('status').textContent='Fix the inputs to update the comparison.';$('export').disabled=true;throw e;}}
function schedule(){inputState();clearTimeout(timer);timer=setTimeout(()=>{try{run();}catch{}},130);}
for(const key of [...Object.keys(limits),'profile'])$(key).addEventListener('input',schedule);
$('reset').addEventListener('click',()=>{for(const[k,v]of Object.entries(defaults))$(k).value=v;inputState();run();});
const metricDefs=[['tracking','Tracking efficiency','%',1],['busEnergy','Estimated bus energy','J',1],['settling','Final settling · 2%','s',2],['ripple','Final power ripple','W',3]];
function value(m,key,unit,d){if(m[key]===null)return key==='settling'&&result.po.at(-1).pmp>1e-8?'Not settled':'N/A';return `${fmt(m[key],d)} ${unit}`;}
function renderMetrics(){const m=result.metrics;$('metrics').innerHTML=metricDefs.map(([key,title,unit,d])=>`<div class="metric"><div class="label">${title}</div><div class="metric-values"><span class="po-text">${m.po[key]===null?'—':fmt(m.po[key],d)}</span><span class="dqn-text">${m.dqn[key]===null?'—':fmt(m.dqn[key],d)}</span></div><div class="names"><span>P&O / DQN demo</span><span>${unit}</span></div></div>`).join('');const defs=[...metricDefs,['pvEnergy','Panel energy','J',1],['conversion','Estimated converter efficiency','%',1],['reachable','Reachable / available MPP energy','%',1]];$('metric-table').innerHTML=defs.map(([key,title,unit,d])=>`<tr><td>${title}</td><td>${value(m.po,key,unit,d)}</td><td>${value(m.dqn,key,unit,d)}</td></tr>`).join('');}
function renderWarnings(){const outside=domainWarnings(result.params);const reach=result.metrics.po.reachable;const msgs=[];if(reach!==null&&reach<99.5)msgs.push(`Converter constraint: reachable equilibrium MPP energy is ${fmt(reach,1)}% of available MPP energy with this ratio, bus and frequency range.`);if(outside.length)msgs.push(`DQN outside its training range: ${outside.join(', ')}. Treat this run as an unvalidated sensitivity experiment.`);if(result.metrics.po.tracking===null)msgs.push('No sunlight in this run. Available panel energy is zero; energy ratios are undefined.');$('warning').hidden=!msgs.length;$('warning').textContent=msgs.join(' ');}
const chartNames={p:['Panel power','W'],v:['Panel voltage','V'],f:['Switching frequency','kHz'],busP:['Estimated bus power','W']};
function axes(w,h,xmax,ymax,unit,xlabel){const pad={l:57,r:16,t:25,b:45};const x=t=>pad.l+t/xmax*(w-pad.l-pad.r),y=v=>h-pad.b-v/ymax*(h-pad.t-pad.b);let s=`<text x="${pad.l}" y="14" font-size="13" fill="#536779">${unit}</text>`;for(let i=0;i<=4;i++){const yy=y(ymax*i/4);s+=`<line x1="${pad.l}" x2="${w-pad.r}" y1="${yy}" y2="${yy}" stroke="#e0e8ee"/><text x="${pad.l-10}" y="${yy+5}" text-anchor="end" font-size="13" fill="#536779">${(ymax*i/4).toFixed(ymax<2?2:ymax<20?1:0)}</text>`;}for(let i=0;i<=6;i++){const xx=x(xmax*i/6);s+=`<line x1="${xx}" x2="${xx}" y1="${pad.t}" y2="${h-pad.b}" stroke="#edf2f5"/><text x="${xx}" y="${h-pad.b+22}" text-anchor="middle" font-size="13" fill="#536779">${(xmax*i/6).toFixed(xmax<20?1:0)}</text>`;}s+=`<text x="${(w+pad.l-pad.r)/2}" y="${h-3}" text-anchor="middle" font-size="13" fill="#536779">${xlabel}</text>`;return {x,y,pad,s};}
const path=(rows,key,x,y,xkey='t')=>rows.map((r,i)=>`${i?'L':'M'}${x(r[xkey]).toFixed(2)},${y(r[key]).toFixed(2)}`).join(' ');
function render(){if(!result)return;const p=result.params,pr=result.po[cursor],dr=result.dqn[cursor];$('cursor-label').textContent=fmt(pr.t,2)+' s';$('chart-title').textContent=chartNames[view][0];const w=900,h=340,ref=view==='p'?'pmp':view==='v'?'vmp':null;const ymax=Math.max(1,...result.po.map(r=>Math.max(r[view],ref?r[ref]:0)),...result.dqn.map(r=>r[view]))*1.12;const {x,y,pad,s}=axes(w,h,p.duration,ymax,chartNames[view][1],'Time (s)');let body=s;
 if(p.profile==='eclipse'){body+=`<rect x="${x(p.duration*.35)}" y="${pad.t}" width="${x(p.duration*.7)-x(p.duration*.35)}" height="${h-pad.t-pad.b}" fill="#8094a3" opacity=".08"/><text x="${x(p.duration*.525)}" y="${pad.t+17}" text-anchor="middle" font-size="13" fill="#536779">Eclipse</text>`;}else if(p.profile==='step')body+=`<line x1="${x(p.duration*.45)}" x2="${x(p.duration*.45)}" y1="${pad.t}" y2="${h-pad.b}" stroke="#bacbd6" stroke-dasharray="4 4"/>`;
 if(ref)body+=`<path d="${path(result.po,ref,x,y)}" fill="none" stroke="${palette.mpp}" stroke-width="1.7" stroke-dasharray="6 5"/>`;
 for(const key of ['po','dqn'])body+=`<path d="${path(result[key],view,x,y)}" fill="none" stroke="${palette[key]}" stroke-width="2.4" stroke-linejoin="round"/>`;
 body+=`<line x1="${x(pr.t)}" x2="${x(pr.t)}" y1="${pad.t}" y2="${h-pad.b}" stroke="#435f75" stroke-width="1" stroke-dasharray="3 3"/>`;
 for(const[key,row]of[['po',pr],['dqn',dr]])body+=`<circle cx="${x(row.t)}" cy="${y(row[view])}" r="4.5" fill="${palette[key]}" stroke="#fff" stroke-width="2"/>`;
 $('response').innerHTML=`<svg id="response-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${chartNames[view][0]} over time for P and O and demonstration DQN. Use the time slider for numerical values."><title>${chartNames[view][0]} comparison</title>${body}</svg>`;
 const move=e=>{const svg=$('response-svg'),r=svg.getBoundingClientRect();const xx=(e.clientX-r.left)/r.width*w;const t=clampLocal((xx-pad.l)/(w-pad.l-pad.r),0,1)*p.duration;cursor=Math.min(result.po.length-1,Math.round(t/p.dt));$('cursor').value=cursor;render();};$('response-svg').addEventListener('pointerdown',move);
 $('readout').innerHTML=`<div><strong>Environment</strong><br>${fmt(pr.g,0)} W/m² · ${fmt(p.temp,0)} °C<br>Available MPP ${fmt(pr.pmp)} W at ${fmt(pr.vmp)} V</div><div><strong class="po-text">P&O</strong><br>${fmt(pr.p)} W · ${fmt(pr.v)} V · ${fmt(pr.i,3)} A<br>${fmt(pr.f)} kHz · bus ${fmt(pr.busP)} W</div><div><strong class="dqn-text">DQN demo</strong><br>${fmt(dr.p)} W · ${fmt(dr.v)} V · ${fmt(dr.i,3)} A<br>${fmt(dr.f)} kHz · bus ${fmt(dr.busP)} W</div>`;
 renderPV(pr,dr,p);
}
const clampLocal=(v,a,b)=>Math.min(b,Math.max(a,v));
function renderPV(pr,dr,p){const pv=panel(pr.g,p),w=500,h=275,vmax=pv.voc||p.voc,ymax=Math.max(1,pv.pmp*1.15);const{x,y,pad,s}=axes(w,h,vmax,ymax,'W','Panel voltage (V)');const points=Array.from({length:151},(_,i)=>{const v=i/150*vmax;return {v,p:v*current(v,pv)};});const a=equilibrium(p.fmax,pv,p),b=equilibrium(p.fmin,pv,p);let body=s;
 if(pv.voc)body+=`<rect x="${x(a)}" y="${pad.t}" width="${Math.max(0,x(b)-x(a))}" height="${h-pad.b-pad.t}" fill="#ddeaf1" fill-opacity=".3" stroke="#93b3c7" stroke-dasharray="4 4"/>`;
 body+=`<path d="${path(points,'p',x,y,'v')}" fill="none" stroke="#334f65" stroke-width="2"/>`;
 if(pv.pmp)body+=`<circle cx="${x(pv.vmp)}" cy="${y(pv.pmp)}" r="5" fill="#fff" stroke="#334f65" stroke-width="2"/>`;
 for(const[key,row]of[['po',pr],['dqn',dr]])body+=`<circle cx="${x(row.v)}" cy="${y(row.p)}" r="5" fill="${palette[key]}" stroke="#fff" stroke-width="1.5"><title>${key==='po'?'P&O':'DQN demo'}: ${fmt(row.v)} V, ${fmt(row.p)} W</title></circle>`;
 $('pv-chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Panel power voltage curve at ${fmt(pr.t)} seconds, with both operating points and the frequency limited reachable band."><title>Panel power voltage curve</title>${body}</svg>`;$('pv-condition').textContent=`At ${fmt(pr.t,2)} s · ${fmt(pr.g,0)} W/m²`;
}
$('cursor').addEventListener('input',e=>{cursor=Number(e.target.value);render();});
for(const button of document.querySelectorAll('[data-view]'))button.addEventListener('click',()=>{view=button.dataset.view;for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',String(b===button));render();});
function csv(){const meta=`# CubeSat MPPT Lab: representative reduced-model results; not thesis validation\n# Inputs: ${JSON.stringify(result.params)}\n# DQN provenance: ${JSON.stringify(result.policy)}\n`;const headers=['time_s','irradiance_W_m2','temperature_C','available_mpp_W','available_vmpp_V','reachable_mpp_W','po_voltage_V','po_current_A','po_panel_power_W','po_estimated_bus_power_W','po_frequency_kHz','po_reference_V','po_applied_action_multiplier','dqn_voltage_V','dqn_current_A','dqn_panel_power_W','dqn_estimated_bus_power_W','dqn_frequency_kHz','dqn_reference_V','dqn_applied_action_multiplier'];const rows=result.po.map((a,i)=>{const b=result.dqn[i];return [a.t,a.g,result.params.temp,a.pmp,a.vmp,a.reachable,a.v,a.i,a.p,a.busP,a.f,a.ref,a.action,b.v,b.i,b.p,b.busP,b.f,b.ref,b.action].map(x=>Number(x.toFixed(8))).join(',');});return meta+headers.join(',')+'\n'+rows.join('\n')+'\n';}
$('export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([csv()],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cubesat-mppt-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.querySelector('a[href="#model-notes"]').addEventListener('click',()=>$('model-notes').open=true);
function setInputs(config){if(!config||typeof config!=='object'||Array.isArray(config))throw Error('Expected an input object.');const allowed=Object.keys(defaults);for(const k of Object.keys(config))if(!allowed.includes(k))throw Error('Unknown input: '+k);const p=validate({...result?.params||defaults,...config});for(const[k,v]of Object.entries(p))$(k).value=v;inputState();run(p);return summary();}
function summary(){if(!result)throw Error('Simulator is not ready.');return {params:result.params,metrics:result.metrics,dqnOutsideTrainingRange:domainWarnings(result.params),assumptions:'Empirical PV, ideal model-based inner PFM loop, averaged FSSCC, demonstration DQN, quasi-static bus power. Not thesis validation.'};}
window.mpptLab={setInputs,getSummary:summary,getResults:()=>result,exportCsv:csv};
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const schema={type:'object',properties:Object.fromEntries(Object.entries(limits).map(([k,[min,max]])=>[k,{type:'number',minimum:min,maximum:max}]).concat([['profile',{type:'string',enum:['constant','step','eclipse']}]])),additionalProperties:false};for(const tool of [{name:'run_mppt_comparison',title:'Run MPPT comparison',description:'Apply representative simulator inputs and recompute both controllers. This changes the visible experiment, not a physical system.',inputSchema:schema,annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>setInputs(input)},{name:'get_mppt_summary',title:'Read MPPT results',description:'Read the current simulated metrics, inputs and DQN training-range warnings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:input=>{if(input&&Object.keys(input).length)throw Error('No input properties are accepted.');return summary();}}]){try{Promise.resolve(ctx.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
inputState();fetch('policy.json').then(r=>{if(!r.ok)throw Error('Policy could not be loaded. Reload the page to retry.');return r.json();}).then(data=>{policy=data;run();registerTools();}).catch(e=>{$('error').hidden=false;$('error').textContent=e.message;$('status').textContent='Simulation could not start.';});
